{
  "application": "ppt-generation",
  "case_id": "case-paper-gemma3",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "AI safety researchers, frontier AI lab leadership, and policy analysts tracking autonomous AI capabilities",
    "tone": "analytical, data-forward, technical"
  },
  "brief": {
    "title": "Measuring AI Ability to Complete Long Software Tasks: Time Horizon Doubling Every 7 Months",
    "one_liner": "Frontier AI agents' task-completion time horizon has been doubling roughly every 7 months since 2019, with current models autonomously completing tasks that take skilled humans nearly 2 hours.",
    "goal": "The audience should understand the time-horizon metric, the exponential growth trend in autonomous AI task completion, the key drivers behind this progress, and the implications for AI safety and workforce automation over the next 5 years."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "Measuring AI Ability to Complete Long Software Tasks",
      "objective": "Cover slide with paper title, authors (METR), and key headline: 50% time horizon doubling every ~7 months. Include paper source reference."
    },
    {
      "id": "time-horizon-metric-explained",
      "title": "A New Metric: 50% Task-Completion Time Horizon",
      "objective": "Explain the time-horizon methodology using a 3-step visual flow diagram: (1) create diverse task suite of 170 tasks, (2) measure human timing and AI success rates, (3) fit logistic model to find the task duration at which AI succeeds 50% of the time. Reference the methodology figure (figure_2.jpg)."
    },
    {
      "id": "task-suite-overview",
      "title": "170 Tasks Spanning 3 Seconds to 8 Hours of Human Effort",
      "objective": "Present the task suite composition (HCAST 97 tasks, RE-Bench 7 tasks, SWAA 66 tasks) and show the example tasks table with durations from 3 seconds (find_shell_script) to 8 hours (cuda_backtesting). Use a table visualization."
    },
    {
      "id": "exponential-trend-since-2019",
      "title": "AI Task Horizon Grew from 2 Seconds (GPT-2) to ~1 Hour 50 Minutes (o3) in 6 Years",
      "objective": "Show the main exponential trend chart (figure_1.jpg) of 50% time horizon vs. model release date. Highlight the doubling time of ~207 days (~7 months), R²=0.97, and the trajectory from GPT-2 (~2 sec) through GPT-4 (0314) (~5 minutes) to o3 (~1 hour 50 minutes)."
    },
    {
      "id": "model-by-model-success-curves",
      "title": "Success Probability Drops Sharply as Task Length Increases for All Models",
      "objective": "Display the per-model success probability curves (figure_3.jpg) showing how each model's success rate declines with task length. Highlight that frontier models like Claude 3.7 Sonnet (54 min) and o3 (1h50m) push the curve rightward compared to older models like GPT-2 (2 sec)."
    },
    {
      "id": "drivers-of-progress",
      "title": "Reasoning, Tool Use, and Error Recovery Drive Time Horizon Growth",
      "objective": "Summarize the key capability drivers: improved logical reasoning, better tool use, greater reliability and self-awareness in task execution, and ability to adapt to mistakes. Note the limitation that performance is much lower on less structured 'messier' tasks."
    },
    {
      "id": "extrapolation-and-forecasts",
      "title": "Extrapolation Predicts Month-Long Task Automation by 2028–2031",
      "objective": "Present the forward extrapolation: if the trend continues, AI reaches >1 month time horizon (167 work hours) between mid-2028 and mid-2031. Note the 2023–2025 horizon growth rate is ~20% faster than the 2019–2025 rate. Discuss caveats around external validity and trend changes."
    },
    {
      "id": "implications-and-takeaways",
      "title": "Takeaways: Exponential Autonomous Capability Growth Demands Proactive Safety Governance",
      "objective": "Summarize 5 key takeaways: (1) 50% time horizon is a robust, intuitive metric for tracking AI autonomy with R²=0.97 over 6 years; (2) doubling every ~7 months with possible acceleration since 2024; (3) current frontier at ~2 hours of human-equivalent work (o3); (4) external validity remains an open question—tasks may not perfectly represent real-world intellectual labor; (5) key limitations include poor performance on unstructured tasks and uncertain generalization to real-world job distributions."
    }
  ]
}

